"use client"

import { ChevronRight, PanelLeft, Pin, Trash2 } from "lucide-react"
import {
  forwardRef,
  type ButtonHTMLAttributes,
  type ReactNode,
} from "react"

import { useSidebarDnd } from "@/components/ui/sidebar-dnd"
import { SidebarEdgeDropZone } from "@/components/ui/sidebar-drop-zones"
import { cn } from "@/lib/utils"

export const SIDEBAR_WIDTH_EXPANDED = 290
export const SIDEBAR_WIDTH_COLLAPSED = 60

type SideRowProps = ButtonHTMLAttributes<HTMLButtonElement> & {
  icon: ReactNode
  children: ReactNode
  hint?: ReactNode
}

export const SideRow = forwardRef<HTMLButtonElement, SideRowProps>(
  function SideRow({ icon, children, hint, onClick, className, ...rest }, ref) {
    return (
      <button
        ref={ref}
        type="button"
        onClick={onClick}
        className={
          className ??
          "flex w-full items-center gap-2.5 rounded-md px-2.5 py-1.5 text-left text-[13.5px]"
        }
        style={{
          background: "transparent",
          border: 0,
          color: "var(--ink)",
        }}
        onMouseEnter={(e) => {
          e.currentTarget.style.background = "var(--hover)"
        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.background = "transparent"
        }}
        {...rest}
      >
        <span className="inline-flex" style={{ color: "var(--ink-2)" }}>
          {icon}
        </span>
        <span className="min-w-0 flex-1">{children}</span>
        {hint ? (
          <span
            className="shrink-0 text-[11px]"
            style={{ color: "var(--ink-3)" }}
          >
            {hint}
          </span>
        ) : null}
      </button>
    )
  }
)

type SideIconBtnProps = ButtonHTMLAttributes<HTMLButtonElement> & {
  label: string
  children: ReactNode
}

export const SideIconBtn = forwardRef<HTMLButtonElement, SideIconBtnProps>(
  function SideIconBtn(
    { label, onClick, children, className, ...rest },
    ref
  ) {
    return (
      <button
        ref={ref}
        type="button"
        onClick={onClick}
        title={label}
        aria-label={label}
        className={className ?? "rounded-md p-2"}
        style={{ background: "transparent", border: 0, color: "var(--ink-2)" }}
        onMouseEnter={(e) => {
          e.currentTarget.style.background = "var(--hover)"
        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.background = "transparent"
        }}
        {...rest}
      >
        {children}
      </button>
    )
  }
)

export function SidebarCollapsibleSection({
  title,
  open,
  onToggle,
  count,
  description,
  className,
  children,
}: {
  title: string
  open: boolean
  onToggle: () => void
  count: number
  description?: ReactNode
  className?: string
  children: ReactNode
}) {
  return (
    <div className={className}>
      <button
        type="button"
        onClick={onToggle}
        className="flex w-full items-center gap-1.5 px-2.5 pb-1 pt-1 uppercase"
        style={{
          background: "transparent",
          border: 0,
          color: "var(--ink-3)",
          fontSize: 11,
          fontWeight: 500,
          letterSpacing: ".04em",
        }}
      >
        <span
          className="inline-flex transition-transform"
          style={{ transform: open ? "rotate(90deg)" : "none" }}
        >
          <ChevronRight className="h-3 w-3" />
        </span>
        <span>{title}</span>
        <span className="ml-auto" style={{ fontWeight: 400 }}>
          {count}
        </span>
      </button>
      {open && description ? (
        <div
          className="px-2.5 pb-1.5"
          style={{ fontSize: 12, color: "var(--ink-3)" }}
        >
          {description}
        </div>
      ) : null}
      {open ? children : null}
    </div>
  )
}

export function SidebarEmptyState({ children }: { children: ReactNode }) {
  return (
    <div
      className="px-2.5 py-2"
      style={{ fontSize: 12, color: "var(--ink-3)" }}
    >
      {children}
    </div>
  )
}

export type ChatSidebarProps = {
  collapsed: boolean
  onCollapsedChange: (collapsed: boolean) => void
  brand?: ReactNode
  nav?: ReactNode
  rail?: ReactNode
  children?: ReactNode
  footer?: ReactNode
  /** Extra absolute overlays inside the expanded panel (custom drop zones). */
  overlays?: ReactNode
  /** When inside ChatSidebarDnd, show pin/trash edge zones while dragging. */
  edgeZones?: boolean
  pinLabel?: string
  trashLabel?: string
  widthExpanded?: number
  widthCollapsed?: number
  className?: string
}

export function ChatSidebar({
  collapsed,
  onCollapsedChange,
  brand,
  nav,
  rail,
  children,
  footer,
  overlays,
  edgeZones = false,
  pinLabel = "Drop here to pin",
  trashLabel = "Drop here to delete",
  widthExpanded = SIDEBAR_WIDTH_EXPANDED,
  widthCollapsed = SIDEBAR_WIDTH_COLLAPSED,
  className,
}: ChatSidebarProps) {
  const { activeDragId, pinZoneId, trashZoneId } = useSidebarDnd()

  return (
    <div
      className={cn(
        "lc-sidebar-wrap relative flex h-full min-h-0 min-w-0 flex-shrink-0 overflow-hidden transition-[width] duration-300 ease-in-out",
        className
      )}
      style={{
        width: collapsed ? widthCollapsed : widthExpanded,
        background: "var(--bg-sidebar)",
        borderRight: "1px solid var(--border)",
      }}
    >
      <div
        hidden={!collapsed}
        className="absolute inset-y-0 left-0 z-20 flex flex-col items-center gap-1.5 py-3"
        style={{ width: widthCollapsed }}
      >
        <SideIconBtn
          label="Open sidebar"
          onClick={() => onCollapsedChange(false)}
        >
          <PanelLeft className="h-4 w-4" />
        </SideIconBtn>
        {rail}
        <div className="flex-1" />
        {footer}
      </div>

      <div
        hidden={collapsed}
        className="relative flex h-full min-h-0 flex-col"
        style={{ width: widthExpanded, minWidth: widthExpanded }}
      >
        <div
          className="flex items-center justify-between gap-2 px-3 pb-2 pt-3"
          style={{
            background: "var(--bg-sidebar)",
            borderBottom: "1px solid var(--border)",
          }}
        >
          <div className="min-w-0 flex-1">{brand}</div>
          <button
            type="button"
            onClick={() => onCollapsedChange(true)}
            title="Collapse sidebar"
            className="inline-flex items-center justify-center rounded-md p-1.5"
            style={{
              background: "transparent",
              border: 0,
              color: "var(--ink-2)",
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.background = "var(--bg-soft)"
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.background = "transparent"
            }}
          >
            <PanelLeft className="h-[17px] w-[17px]" />
          </button>
        </div>

        {nav ? <div className="px-2 pb-0.5 pt-2">{nav}</div> : null}

        <div className="lc-scroll flex-1 overflow-y-auto px-2 pb-2 pt-3">
          {children}
        </div>

        {footer ? (
          <div
            className="border-t px-2 py-2"
            style={{ borderColor: "var(--border)" }}
          >
            {footer}
          </div>
        ) : null}

        {overlays}
        {edgeZones && activeDragId ? (
          <>
            <SidebarEdgeDropZone
              id={pinZoneId}
              edge="top"
              icon={<Pin className="h-3.5 w-3.5" />}
              label={pinLabel}
              tone="accent"
            />
            <SidebarEdgeDropZone
              id={trashZoneId}
              edge="bottom"
              icon={<Trash2 className="h-3.5 w-3.5" />}
              label={trashLabel}
              tone="danger"
            />
          </>
        ) : null}
      </div>
    </div>
  )
}

/** @deprecated Prefer ChatSidebarItem from sidebar-item. */
export function ChatSidebarItemRow({
  title,
  active,
  onClick,
}: {
  title: string
  active?: boolean
  onClick?: () => void
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className="flex w-full items-center rounded-md px-2.5 py-1.5 text-left text-[13px]"
      style={{
        background: active ? "var(--hover)" : "transparent",
        border: 0,
        color: "var(--ink)",
      }}
      onMouseEnter={(e) => {
        if (!active) e.currentTarget.style.background = "var(--hover)"
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.background = active
          ? "var(--hover)"
          : "transparent"
      }}
    >
      <span className="min-w-0 flex-1 truncate">{title}</span>
    </button>
  )
}

export type { ChatSidebarItemData } from "@/components/ui/sidebar-item"
export {
  ChatSidebarItem,
  ChatSidebarItemGhost,
  ChatSidebarItemList,
} from "@/components/ui/sidebar-item"
export { ChatSidebarDnd, useSidebarDnd } from "@/components/ui/sidebar-dnd"
export {
  SidebarDropZone,
  SidebarEdgeDropZone,
} from "@/components/ui/sidebar-drop-zones"

"use client"

import {
  useDraggable,
  type DraggableAttributes,
  type DraggableSyntheticListeners,
} from "@dnd-kit/core"
import { Pencil, Pin, PinOff, Trash2 } from "lucide-react"
import {
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react"

import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuSeparator,
  ContextMenuTrigger,
} from "@/components/ui/context-menu"

export type SidebarItemStatus =
  | "idle"
  | "active"
  | "streaming"
  | "pending"
  | "fault"

export type SidebarItemMenuAction = {
  id: string
  label: string
  icon?: ReactNode
  onSelect: () => void
  destructive?: boolean
  separatorBefore?: boolean
}

export type ChatSidebarItemData = {
  id: string
  title: string
  pinned?: boolean
  status?: SidebarItemStatus
  /** Leading icon overrides status dot. */
  leading?: ReactNode
}

function statusChrome(
  active: boolean,
  status: SidebarItemStatus | undefined
): { variant: string; dotStyle: CSSProperties; iconColor: string } {
  const baseDot: CSSProperties = {
    width: 8,
    height: 8,
    borderRadius: 9999,
    flexShrink: 0,
  }
  const resolved = status ?? (active ? "active" : "idle")
  if (resolved === "fault") {
    const fill = "color-mix(in oklab, var(--destructive) 82%, var(--bg-sidebar))"
    return {
      variant: "fault",
      dotStyle: { ...baseDot, background: fill },
      iconColor: fill,
    }
  }
  if (resolved === "streaming") {
    return {
      variant: "streaming",
      dotStyle: { ...baseDot, background: "var(--primary)" },
      iconColor: "var(--primary)",
    }
  }
  if (resolved === "pending") {
    return {
      variant: "pending",
      dotStyle: { ...baseDot, background: "#ca8a04" },
      iconColor: "#ca8a04",
    }
  }
  if (resolved === "active" || active) {
    const fill = "color-mix(in oklab, var(--ink-3) 58%, var(--bg-sidebar))"
    return {
      variant: "active",
      dotStyle: { ...baseDot, background: fill },
      iconColor: fill,
    }
  }
  const fill = "color-mix(in oklab, var(--ink-3) 88%, var(--bg-sidebar))"
  return {
    variant: "idle",
    dotStyle: { ...baseDot, background: fill },
    iconColor: fill,
  }
}

type ItemRowProps = {
  item: ChatSidebarItemData
  active?: boolean
  editing: boolean
  setEditing: (v: boolean) => void
  onSelect?: () => void
  onRename?: (title: string) => void
  onTogglePin?: () => void
  onDelete?: () => void
  menuActions?: SidebarItemMenuAction[]
  dragAttrs?: DraggableAttributes
  dragListeners?: DraggableSyntheticListeners
  dragNodeRef?: (el: HTMLDivElement | null) => void
  isBeingDragged?: boolean
  showDivider?: boolean
  showStatusDot?: boolean
}

function ItemRow({
  item,
  active = false,
  editing,
  setEditing,
  onSelect,
  onRename,
  onTogglePin,
  onDelete,
  menuActions = [],
  dragAttrs,
  dragListeners,
  dragNodeRef,
  isBeingDragged,
  showDivider,
  showStatusDot = true,
}: ItemRowProps) {
  const [draft, setDraft] = useState(item.title || "")
  const inputRef = useRef<HTMLInputElement>(null)
  const isPinned = !!item.pinned
  const chrome = statusChrome(active, item.status)

  useEffect(() => {
    if (editing) {
      inputRef.current?.focus()
      inputRef.current?.select()
    }
  }, [editing])

  const startEdit = () => {
    setDraft(item.title || "")
    setEditing(true)
  }

  const commit = () => {
    setEditing(false)
    const next = draft.trim()
    if (next && next !== (item.title || "")) onRename?.(next)
  }

  const cancel = () => {
    setEditing(false)
    setDraft(item.title || "")
  }

  const rowStyle: CSSProperties = {
    opacity: isBeingDragged ? 0.4 : 1,
    touchAction: dragListeners ? "none" : undefined,
    ...(showDivider
      ? {
          marginTop: 6,
          paddingTop: 6,
          borderTop: "1px solid var(--border)",
        }
      : {}),
  }

  const shellProps = {
    ref: dragNodeRef,
    ...(dragAttrs ?? {}),
    ...(!editing && dragListeners ? dragListeners : {}),
    className: "group/row relative",
    style: rowStyle,
  }

  if (editing) {
    return (
      <div {...shellProps}>
        <input
          ref={inputRef}
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onBlur={commit}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault()
              commit()
            } else if (e.key === "Escape") {
              e.preventDefault()
              cancel()
            }
          }}
          className="mb-px block w-full truncate py-1.5 pr-2.5 pl-2.5 text-left outline-none"
          style={{
            background: "var(--hover)",
            color: "var(--ink)",
            border: 0,
            borderLeft: "2px solid var(--primary)",
            fontSize: 13.5,
          }}
        />
      </div>
    )
  }

  const builtIn: SidebarItemMenuAction[] = []
  if (onRename) {
    builtIn.push({
      id: "rename",
      label: "Rename",
      icon: <Pencil className="h-3.5 w-3.5" />,
      onSelect: startEdit,
    })
  }
  if (onTogglePin) {
    builtIn.push({
      id: "pin",
      label: isPinned ? "Unpin" : "Pin",
      icon: isPinned ? (
        <PinOff className="h-3.5 w-3.5" />
      ) : (
        <Pin className="h-3.5 w-3.5" />
      ),
      onSelect: onTogglePin,
    })
  }
  if (onDelete) {
    builtIn.push({
      id: "delete",
      label: "Delete",
      icon: <Trash2 className="h-3.5 w-3.5" />,
      onSelect: onDelete,
      destructive: true,
      separatorBefore: builtIn.length > 0 || menuActions.length > 0,
    })
  }

  const actions = [...menuActions, ...builtIn]
  const rowButton = (
    <div {...shellProps}>
      <button
        type="button"
        onClick={onSelect}
        onDoubleClick={onRename ? startEdit : undefined}
        title={item.title || "Untitled"}
        className="mb-px flex w-full items-center gap-1.5 truncate py-1.5 pr-2.5 pl-2.5 text-left"
        style={{
          background: "transparent",
          color: "var(--ink)",
          border: 0,
          borderLeft: active
            ? "2px solid var(--primary)"
            : "2px solid transparent",
          fontSize: 13.5,
          fontWeight: active ? 500 : 400,
          cursor: dragListeners ? "grab" : "pointer",
        }}
        onMouseEnter={(e) => {
          if (!active) e.currentTarget.style.background = "var(--hover)"
        }}
        onMouseLeave={(e) => {
          if (!active) e.currentTarget.style.background = "transparent"
        }}
      >
        {isPinned && (
          <Pin
            className="h-3 w-3 flex-shrink-0"
            style={{ color: "var(--primary)" }}
          />
        )}
        {item.leading ? (
          <span className="inline-flex flex-shrink-0">{item.leading}</span>
        ) : showStatusDot && !isPinned ? (
          <span
            className="h-2 w-2 flex-shrink-0 rounded-full"
            data-sidebar-item-dot={chrome.variant}
            style={chrome.dotStyle}
            aria-hidden
          />
        ) : null}
        <span className="flex-1 truncate">{item.title || "Untitled"}</span>
      </button>
    </div>
  )

  if (actions.length === 0) return rowButton

  return (
    <ContextMenu>
      <ContextMenuTrigger asChild>{rowButton}</ContextMenuTrigger>
      <ContextMenuContent className="w-40">
        {actions.map((action) => (
          <div key={action.id}>
            {action.separatorBefore ? <ContextMenuSeparator /> : null}
            <ContextMenuItem
              onSelect={() => action.onSelect()}
              variant={action.destructive ? "destructive" : "default"}
            >
              {action.icon}
              <span>{action.label}</span>
            </ContextMenuItem>
          </div>
        ))}
      </ContextMenuContent>
    </ContextMenu>
  )
}

export type ChatSidebarItemProps = {
  item: ChatSidebarItemData
  active?: boolean
  onSelect?: () => void
  onRename?: (title: string) => void
  onTogglePin?: () => void
  onDelete?: () => void
  menuActions?: SidebarItemMenuAction[]
  draggable?: boolean
  isBeingDragged?: boolean
  showDivider?: boolean
  showStatusDot?: boolean
}

export function ChatSidebarItem({
  item,
  active,
  onSelect,
  onRename,
  onTogglePin,
  onDelete,
  menuActions,
  draggable = false,
  isBeingDragged = false,
  showDivider,
  showStatusDot,
}: ChatSidebarItemProps) {
  const [editing, setEditing] = useState(false)
  const { attributes, listeners, setNodeRef } = useDraggable({
    id: item.id,
    disabled: !draggable || editing,
  })

  return (
    <ItemRow
      item={item}
      active={active}
      editing={editing}
      setEditing={setEditing}
      onSelect={onSelect}
      onRename={onRename}
      onTogglePin={onTogglePin}
      onDelete={onDelete}
      menuActions={menuActions}
      dragAttrs={draggable ? attributes : undefined}
      dragListeners={draggable ? listeners : undefined}
      dragNodeRef={draggable ? setNodeRef : undefined}
      isBeingDragged={isBeingDragged}
      showDivider={showDivider}
      showStatusDot={showStatusDot}
    />
  )
}

export function ChatSidebarItemList({
  items,
  activeId,
  activeDragId,
  onSelect,
  onRename,
  onTogglePin,
  onDelete,
  getMenuActions,
  draggable = true,
}: {
  items: ChatSidebarItemData[]
  activeId?: string
  activeDragId?: string | null
  onSelect?: (id: string) => void
  onRename?: (id: string, title: string) => void
  onTogglePin?: (id: string, pinned: boolean) => void
  onDelete?: (id: string) => void
  getMenuActions?: (item: ChatSidebarItemData) => SidebarItemMenuAction[]
  draggable?: boolean
}) {
  return (
    <>
      {items.map((item, i) => {
        const showDivider =
          i > 0 && !!items[i - 1].pinned && !item.pinned
        return (
          <ChatSidebarItem
            key={item.id}
            item={item}
            active={item.id === activeId}
            isBeingDragged={activeDragId === item.id}
            showDivider={showDivider}
            draggable={draggable}
            onSelect={onSelect ? () => onSelect(item.id) : undefined}
            onRename={
              onRename ? (title) => onRename(item.id, title) : undefined
            }
            onTogglePin={
              onTogglePin
                ? () => onTogglePin(item.id, !item.pinned)
                : undefined
            }
            onDelete={onDelete ? () => onDelete(item.id) : undefined}
            menuActions={getMenuActions?.(item)}
          />
        )
      })}
    </>
  )
}

export function ChatSidebarItemGhost({
  item,
  active,
}: {
  item: ChatSidebarItemData
  active?: boolean
}) {
  const chrome = statusChrome(!!active, item.status)
  return (
    <div
      className="flex items-center gap-1.5 truncate rounded-md py-1.5 pr-3 pl-2.5"
      style={{
        background: "var(--bg-sidebar)",
        color: "var(--ink)",
        border: "1px solid var(--primary)",
        boxShadow: "0 8px 18px -8px rgba(0,0,0,.35)",
        fontSize: 13.5,
        width: 264,
        cursor: "grabbing",
      }}
    >
      {item.pinned && (
        <Pin
          className="h-3 w-3 flex-shrink-0"
          style={{ color: "var(--primary)" }}
        />
      )}
      {!item.pinned && !item.leading ? (
        <span
          className="h-2 w-2 flex-shrink-0 rounded-full"
          style={chrome.dotStyle}
          aria-hidden
        />
      ) : null}
      {item.leading}
      <span className="flex-1 truncate">{item.title || "Untitled"}</span>
    </div>
  )
}

"use client"

import {
  DndContext,
  DragOverlay,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  type DragEndEvent,
  type DragStartEvent,
} from "@dnd-kit/core"
import {
  createContext,
  useContext,
  useMemo,
  useState,
  type ReactNode,
} from "react"

export type SidebarDndDrop =
  | { action: "pin"; id: string }
  | { action: "delete"; id: string }
  | { action: "custom"; id: string; overId: string }

type SidebarDndContextValue = {
  activeDragId: string | null
  pinZoneId: string
  trashZoneId: string
}

const SidebarDndCtx = createContext<SidebarDndContextValue>({
  activeDragId: null,
  pinZoneId: "pin-zone",
  trashZoneId: "trash-zone",
})

export function useSidebarDnd() {
  return useContext(SidebarDndCtx)
}

export type ChatSidebarDndProps = {
  children: ReactNode
  renderOverlay?: (id: string) => ReactNode
  onDrop?: (drop: SidebarDndDrop) => void
  pinZoneId?: string
  trashZoneId?: string
}

export function ChatSidebarDnd({
  children,
  renderOverlay,
  onDrop,
  pinZoneId = "pin-zone",
  trashZoneId = "trash-zone",
}: ChatSidebarDndProps) {
  const [activeDragId, setActiveDragId] = useState<string | null>(null)
  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 6 } }),
    useSensor(KeyboardSensor)
  )

  const value = useMemo(
    () => ({ activeDragId, pinZoneId, trashZoneId }),
    [activeDragId, pinZoneId, trashZoneId]
  )

  const handleDragStart = (e: DragStartEvent) =>
    setActiveDragId(String(e.active.id))
  const handleDragCancel = () => setActiveDragId(null)
  const handleDragEnd = (e: DragEndEvent) => {
    const id = String(e.active.id)
    const overId = e.over?.id ? String(e.over.id) : null
    setActiveDragId(null)
    if (!overId || !onDrop) return
    if (overId === pinZoneId) onDrop({ action: "pin", id })
    else if (overId === trashZoneId) onDrop({ action: "delete", id })
    else onDrop({ action: "custom", id, overId })
  }

  return (
    <DndContext
      sensors={sensors}
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
      onDragCancel={handleDragCancel}
    >
      <SidebarDndCtx.Provider value={value}>{children}</SidebarDndCtx.Provider>
      <DragOverlay dropAnimation={null}>
        {activeDragId && renderOverlay ? renderOverlay(activeDragId) : null}
      </DragOverlay>
    </DndContext>
  )
}

"use client"

import { useDroppable } from "@dnd-kit/core"
import type { ReactNode } from "react"

export function SidebarEdgeDropZone({
  id,
  edge,
  icon,
  label,
  tone,
}: {
  id: string
  edge: "top" | "bottom"
  icon: ReactNode
  label: string
  tone: "accent" | "danger"
}) {
  const { setNodeRef, isOver } = useDroppable({ id })
  const color = tone === "danger" ? "var(--destructive)" : "var(--primary)"
  const tint =
    tone === "danger"
      ? "color-mix(in oklab, var(--bg-sidebar) 72%, var(--destructive))"
      : "color-mix(in oklab, var(--bg-sidebar) 72%, var(--primary))"
  const positionClass =
    edge === "top"
      ? "top-0 right-0 left-0 min-h-[92px] h-[16%]"
      : "right-0 bottom-0 left-0 min-h-[92px] h-[16%]"

  return (
    <div
      ref={setNodeRef}
      className={`pointer-events-auto absolute z-[35] flex items-center justify-center px-3 py-4 ${positionClass}`}
      style={{
        background: isOver ? color : tint,
        border: `1px dashed ${color}`,
        transition: "background 120ms ease, color 120ms ease",
      }}
    >
      <div
        className="flex max-w-full items-center justify-center gap-1.5"
        style={{
          fontSize: 12,
          fontWeight: 600,
          color: isOver ? "var(--primary-foreground)" : color,
        }}
      >
        {icon}
        <span className="truncate">{label}</span>
      </div>
    </div>
  )
}

export function SidebarDropZone({
  id,
  icon,
  label,
  tone,
  visible,
}: {
  id: string
  icon: ReactNode
  label: string
  tone: "accent" | "danger"
  visible: boolean
}) {
  const { setNodeRef, isOver } = useDroppable({ id })
  const color = tone === "danger" ? "var(--destructive)" : "var(--primary)"

  return (
    <div
      ref={setNodeRef}
      aria-hidden={!visible}
      className="overflow-hidden"
      style={{
        maxHeight: visible ? 38 : 0,
        marginTop: visible ? 4 : 0,
        marginBottom: visible ? 4 : 0,
        opacity: visible ? 1 : 0,
        transition:
          "max-height 160ms ease, opacity 160ms ease, margin 160ms ease",
        pointerEvents: visible ? "auto" : "none",
      }}
    >
      <div
        className="mx-1 flex items-center justify-center gap-1.5 rounded-md py-1.5"
        style={{
          fontSize: 12,
          fontWeight: 500,
          color: isOver ? "var(--primary-foreground)" : color,
          background: isOver ? color : "transparent",
          border: `1px dashed ${color}`,
          transition: "background 120ms ease, color 120ms ease",
        }}
      >
        {icon}
        <span>{label}</span>
      </div>
    </div>
  )
}

